// Post effect ChromaticEdges (@gameengine/materials, compiled; do not edit).
struct MaterialParams {
  p_strength: f32,
  p_inner: f32,
  p_outer: f32,
  p_insetTop: f32,
  p_insetBottom: f32,
  p_insetLeft: f32,
  p_insetRight: f32,
};
@group(1) @binding(0) var<uniform> material: MaterialParams;
fn material_post(in: PostInput) -> vec3f {
  let v0: f32 = (material.p_insetLeft - material.p_insetRight);
  let v1: f32 = (v0 + 1.0);
  let v2: f32 = (v1 * 0.5);
  let v3: f32 = (material.p_insetTop - material.p_insetBottom);
  let v4: f32 = (v3 + 1.0);
  let v5: f32 = (v4 * 0.5);
  let v6: vec2f = vec2f(v2, v5);
  let v7: vec2f = (in.screen_uv - v6);
  let v8: vec2f = (v7 * in.size);
  let v9: f32 = length(v8);
  let v10: f32 = max(v9, 0.0001);
  let v11: vec2f = (v8 / v10);
  let v12: f32 = in.size.y;
  let v13: f32 = (v12 / 1080.0);
  let v14: f32 = (material.p_strength * v13);
  let v15: f32 = (material.p_insetLeft + material.p_insetRight);
  let v16: f32 = (v15 * -1.0);
  let v17: f32 = (v16 + 1.0);
  let v18: f32 = (material.p_insetTop + material.p_insetBottom);
  let v19: f32 = (v18 * -1.0);
  let v20: f32 = (v19 + 1.0);
  let v21: vec2f = vec2f(v17, v20);
  let v22: vec2f = (v21 * 0.5);
  let v23: vec2f = (v22 * in.size);
  let v24: f32 = length(v23);
  let v25: f32 = max(v24, 1.0);
  let v26: f32 = (v9 / v25);
  let v27: f32 = smoothstep(material.p_inner, material.p_outer, v26);
  let v28: f32 = clamp(v27, 0.0, 1.0);
  let v29: f32 = (v14 * v28);
  let v30: vec2f = (v11 * v29);
  let v31: vec2f = (v30 * in.texel);
  let v32: vec2f = (in.screen_uv + v31);
  let v33: vec3f = post_color(v32);
  let v34: f32 = v33.x;
  let v35: vec3f = post_color(in.screen_uv);
  let v36: f32 = v35.y;
  let v37: vec2f = (in.screen_uv - v31);
  let v38: vec3f = post_color(v37);
  let v39: f32 = v38.z;
  let v40: vec3f = vec3f(v34, v36, v39);
  return v40;
}
